 if(type==='dodge'){if(state.dragonEco.action){message('Action du dragon déjà utilisée.');return}transaction('Dragon · Esquive',()=>{state.dragonEco.action=true;return 'Les attaques contre le dragon ont désavantage jusqu’à son prochain tour.'});return}
