 if(type==='breath'){if(state.dragonEco.breath||state.dragonEco.action){message('Souffle déjà utilisé.');return}let r=await choose('Souffle du dragon',`<label>Type <select name="type">${['froid','acide','feu','foudre','poison'].map(t=>`<option>${t}</option>`).join('')}</select></label><div class="field-row"><label>Échecs <input name="fail" type="number" min="0" value="1"></label><label>Réussites <input name="success" type="number" min="0" value="0"></label></div>`,[{label:'Résoudre',value:'go'},{label:'Annuler',value:null}]);if(!r.choice)return;let f=Number(r.data.fail),s=Number(r.data.success);if(!Number.isInteger(f)||!Number.isInteger(s)||f<0||s<0||f+s>50){message('Nombre de cibles invalide.');return}transaction('Dragon · Souffle',()=>{let d=damageDice(2,6),amount=f*d.total+s*Math.floor(d.total/2);state.dragonEco.breath=true;state.dragonDamage+=amount;return `DEX DD18 · ${d.total} ${r.data.type} (${d.detail}) par échec, moitié en réussite · ${amount} dégâts cumulés.`})}
