function rest(long){if(!confirm(`Effectuer un repos ${long?'long':'court'} ?`))return;transaction(long?'Repos long':'Repos court',()=>{if(!long)return 'Les emplacements et points de sorcellerie ne reviennent pas. Dépensez les dés de vie avec le bouton Ressources ; la fiole s’active automatiquement.';let old=state.hp;state.hp=72;state.tempHp=0;state.slots={...MAX};state.sp=10;state.featSp=state.featEnabled?2:0;state.hitDice=Math.min(10,state.hitDice+5);state.cureFree=1;state.wings=4;state.flame=1;state.flameArmed=false;state.vial=1;state.eco={action:false,bonus:false,reaction:false,move:false};state.bonusSpell=false;state.leveledAction=false;state.concentration='';state.dragon=null;state.sharedResistance='';state.phase='samoth';return `PV ${old} → 72, emplacements et sorcellerie restaurés, +5 dés de vie maximum, usages journaliers remis. Bâton : récupération à l’aube séparée.`})}
