 if(s.lv&&!staffOnly){let opts=Object.keys(MAX).map(Number).filter(n=>n>=s.lv&&state.slots[n]>0),free=s.id==='cure'&&state.cureFree;let choices=[...(free?['<option value="free">Gratuit</option>']:[]),...opts.map(n=>`<option value="${n}">N${n} · ${state.slots[n]} restant(s)</option>`)];let value=free&&d.free?'free':opts.includes(Number(d.level))?String(d.level):free?'free':String(opts[0]||'');d.free=value==='free';d.level=d.free?1:Number(value);fields.push(`<label class="cast-choice compact-field">Emplacement<select data-cast-field="${free?'free':'level'}" id="castLevel" ${d.useStaff?'disabled':''}>${choices.join('')}</select></label>`)}
